import numpy as np

def f(t):
    return (t - 1)*(t - 2)

def check(p, q):
    """g = f*h, h = x^2+px+q 일 때 두 극한이 모든 실수 a 에서 존재하는가 (수치)"""
    def g(t):
        return f(t)*(t*t + p*t + q)
    h = np.poly1d([1, p, q])
    gp = np.poly1d([1, -3, 2])*h
    crit = [1.0, 2.0] + [float(r.real) for r in np.roots(gp.coeffs) if abs(r.imag) < 1e-9]
    e = 1e-6
    def e1(t):
        return g(t)*abs(f(t))/f(t)
    def e2(t):
        return abs(g(t) - 3*f(t))/g(t)
    for a in crit:
        for fn in (e1, e2):
            try:
                l, r = fn(a - e), fn(a + e)
            except ZeroDivisionError:
                return False
            if abs(l) > 1e3 or abs(r) > 1e3 or abs(l - r) > 1e-2:
                return False
    return True

def cand():
    out = set()
    for p2 in range(-24, 25):
        for q2 in range(-40, 61):
            p, q = p2/2, q2/2
            if check(p, q):
                gm1 = (f(-1))*((-1)**2 + p*(-1) + q)
                out.add(gm1)
    return out

def skill():
    return f(-1)*(f(-1) + 3)

def standard():
    v = cand()
    assert len(v) == 1
    return list(v)[0]

def unique():
    return sorted(cand())
